/**
 * 다른 fixer(sitemap/canonical/og)는 전부 "이미 있는 파일을 AST로 편집"이라 originalText/updatedText
 * 동등 비교로 멱등을 판단한다. 이 fixer는 반대로 "파일이 아예 없을 때만 새로 만든다" — 이미 robots.ts가
 * 있으면 사용자가 이미 의도를 갖고 만든 정책일 수 있어 절대 재구성하지 않는다(추측 금지, fail-closed).
 * 그래서 두 가지 "손대지 않음" 사유를 구분해야 한다: 우리가 이전에 만든 파일이 그대로 있는 경우(멱등
 * 성공, alreadyApplied=true) vs 원래부터 있던/다른 주체가 만든 파일(진짜 충돌, report_only).
 */
export interface RobotsAiPolicyFixPlan {
    applicable: boolean;
    reason: string;
    /** true면 이전에 이 fixer가 만든 파일이 이미 존재(멱등 no-op) — 진짜 충돌(alreadyApplied 없음)과 구분해야 apply.ts가 실패로 오판하지 않는다. */
    alreadyApplied?: boolean;
    updatedText?: string;
}
/** 생성한 파일에 반드시 남기는 마커 — 재실행 시 "우리가 만든 파일"인지 식별하는 유일한 근거. */
